def find_single_element(nums):
    if not nums:
        return None

    left, right = 0, len(nums) - 1

    while left < right:
        mid = (left + right) // 2
        # Check if the middle element is at its correct position
        if nums[mid] != nums[left]:
            right = mid
        else:
            left = mid + 1

    return nums[left]
```

